void component_name_tests(const std::filesystem::path& dir){
    SegmentDocument seed;require(seed.add_tempo(0,123)&&seed.add_note({0,384,0,69,96}),"Name fixture retains playable data");
    auto root=Chunk::parse(seed.save_bytes());
    Chunk unknown;unknown.id="xNam";unknown.data={9,8,7};unknown.padding=0xa5;root.children.push_back(unknown);
    Chunk info;info.id="LIST";info.type="UNFO";Chunk author;author.id="UART";author.data=utf16(L"Author");Chunk name;name.id="UNAM";name.data=utf16(L"Original");info.children={author,unknown,name};root.children.push_back(info);
    const auto before=root.encode();SegmentDocument segment;segment.load(before);segment.select_track_group(1);segment.select(0);
    require(segment.tempos().size()==1&&segment.tempos()[0].selected&&segment.notes().size()==1,"Name fixture has selected Tempo and Sequence before editing");
    require(segment.name()==L"Original"&&!segment.dirty(),"Native Segment name read without edit");
    require(segment.set_name(L"検証 Segment"),"Unicode Segment internal name edit");
    auto expected=root;expected.find("LIST","UNFO")->find("UNAM")->data=utf16(L"検証 Segment");const auto after=expected.encode();
    require(segment.save_bytes()==after&&segment.dirty(),"Only UNAM and enclosing sizes change; unknown padding and author survive");
    require(segment.tempos().size()==1&&segment.tempos()[0].selected&&segment.selected_groups()==1&&segment.notes().size()==1,"Name edit retains timeline selection and Sequence");
    require(segment.undo()&&segment.name()==L"Original"&&segment.save_bytes()==before&&!segment.dirty(),"Name Undo restores entire disk checkpoint");
    for(const auto& invalid:std::vector<std::wstring>{L"",std::wstring(256,L'x'),std::wstring(L"a\0b",3)}){
        require(!segment.set_name(invalid),"Invalid internal name refused");require(segment.save_bytes()==before&&!segment.dirty(),"Rejected name keeps exact bytes and dirty state");
    }
    require(!segment.set_name(L"Original")&&segment.redo()&&segment.save_bytes()==after,"No-op and invalid names retain Redo");
    segment.save((dir/L"NamedSegment.sgp").wstring());require(!segment.dirty(),"Name native save checkpoint");
    SegmentDocument reload;reload.load(read_file((dir/L"NamedSegment.sgp").wstring()));require(reload.name()==L"検証 Segment"&&reload.save_bytes()==after&&!reload.dirty(),"Native name reload byte exact");
    require(segment.undo()&&segment.save_bytes()==before&&segment.dirty()&&segment.redo()&&!segment.dirty(),"Saved name checkpoint tracks Undo/Redo dirty state");
    require(segment.set_name(std::wstring(255,L'n'))&&segment.name().size()==255,"Existing Style policy boundary255 supported");
    require(!segment.set_name(std::wstring(256,L'n')),"Name length256 refused");
    SegmentDocument missing;const auto without=missing.save_bytes();require(missing.set_name(L"Added"),"Missing UNFO/UNAM created");
    auto restored=Chunk::parse(missing.save_bytes());restored.children.pop_back();require(restored.encode()==without,"Missing name creates metadata without altering existing chunks");
    require(missing.undo()&&missing.save_bytes()==without&&missing.redo()&&missing.name()==L"Added","New metadata follows complete history");
    auto duplicate=root;duplicate.children.push_back(info);SegmentDocument ambiguous;ambiguous.load(duplicate.encode());
    const auto ambiguousBefore=ambiguous.save_bytes();rejected([&]{ambiguous.set_name(L"Wrong");},"Ambiguous name container refused");require(ambiguous.save_bytes()==ambiguousBefore&&!ambiguous.dirty(),"Ambiguous container edit leaves document exact");
    duplicate=root;duplicate.find("LIST","UNFO")->children.push_back(name);ambiguous.load(duplicate.encode());
    const auto duplicateBefore=ambiguous.save_bytes();rejected([&]{ambiguous.set_name(L"Wrong");},"Duplicate UNAM refused");require(ambiguous.save_bytes()==duplicateBefore&&!ambiguous.dirty(),"Duplicate name remains exact");
    duplicate=root;duplicate.find("LIST","UNFO")->find("UNAM")->data={1};ambiguous.load(duplicate.encode());
    const auto malformedBefore=ambiguous.save_bytes();rejected([&]{ambiguous.set_name(L"Wrong");},"Malformed optional name refused");require(ambiguous.save_bytes()==malformedBefore&&!ambiguous.dirty(),"Malformed name leaves all bytes exact");
    Framework host;const auto song=host.new_segment(),style=host.new_style();
    host.document(song).load(after);const auto styleBefore=host.style_document(style).save_bytes();
    require(host.set_style_name(style,L"検証 Style")&&host.style_document(style).name()==L"検証 Style","Shared Style edit uses Framework cache/history path");
    require(host.undo_style(style)&&host.style_document(style).save_bytes()==styleBefore&&host.redo_style(style)&&host.style_document(style).name()==L"検証 Style","Shared Style name Undo/Redo");
    const auto styleAfter=host.style_document(style).save_bytes();require(!host.set_style_name(style,L"")&&host.style_document(style).save_bytes()==styleAfter,"Rejected Style name keeps document exact");
    const auto owned=dir/L"Names";std::filesystem::create_directories(owned);
    host.save_segment(song,(owned/L"OwnedSegment.sgp").wstring());host.save_style(style,(owned/L"OwnedStyle.stp").wstring());host.save_project((owned/L"Names.pro").wstring());
    Framework reopened;reopened.open_project((owned/L"Names.pro").wstring());
    require(reopened.document(0).name()==L"検証 Segment"&&reopened.style_document(0).name()==L"検証 Style"&&!reopened.dirty(),"Owned native Project restores both internal names");
    require(reopened.document(0).save_bytes()==after&&reopened.style_document(0).save_bytes()==styleAfter,"Owned name save/reload preserves complete native payloads");
    const auto bandIndex=host.new_band();auto& band=host.band_document(bandIndex);
    require(!reopened.document(0).can_undo()&&!reopened.document(0).can_redo()&&!reopened.style_document(0).can_undo()&&!reopened.style_document(0).can_redo(),"Reloaded component histories start empty");
    require(!band.can_undo()&&!band.can_redo()&&host.add_band_gm_instrument(bandIndex,0,0,64,100),"New Band starts empty and accepts an instrument transaction");
    host.save_band(bandIndex,(owned/L"HistoryBand.bnp").wstring());
    require(band.can_undo()&&!band.can_redo()&&!band.dirty(),"Saving a Band retains its undoable checkpoint");
    require(host.set_band_instrument(bandIndex,0,1,0,64,100)&&host.undo_band(bandIndex),"Band patch change can be undone independently");
    const auto savedBand=band.save_bytes();
    require(band.can_redo()&&!band.dirty()&&!host.set_band_instrument(bandIndex,0,0,0,64,100)&&band.can_redo(),"No-op Band edit retains Redo at clean saved checkpoint");
    require(host.undo_style(style)&&host.style_document(style).can_redo()&&band.save_bytes()==savedBand&&band.can_redo(),"Style Undo preserves independent Band Redo and bytes");
    require(host.document(song).set_name(L"History Segment")&&host.undo_segment(song)&&host.document(song).can_redo(),"Segment exposes its own undone name transaction");
    require(host.set_style_name(style,L"History Style")&&!host.style_document(style).can_redo()&&host.document(song).can_redo()&&band.can_redo(),"Branch edit clears only active Style Redo");
    require(host.redo_segment(song)&&host.redo_band(bandIndex)&&band.instruments()[0].patch==1&&host.style_document(style).name()==L"History Style","Segment and Band Redo leave Style branch unchanged");
    host.save_segment(song,(owned/L"OwnedSegment.sgp").wstring());host.save_style(style,(owned/L"OwnedStyle.stp").wstring());host.save_band(bandIndex,(owned/L"HistoryBand.bnp").wstring());
    require(!host.document(song).dirty()&&!host.style_document(style).dirty()&&!band.dirty()&&host.document(song).can_undo()&&host.style_document(style).can_undo()&&band.can_undo(),"Saving three components keeps separate histories while clearing dirty flags");
    BandDocument bandReload;bandReload.load(read_file((owned/L"HistoryBand.bnp").wstring()));
    require(bandReload.save_bytes()==band.save_bytes()&&!bandReload.can_undo()&&!bandReload.can_redo(),"Band native reload retains bytes without carrying process history");
    BandDocument bandSeed;
    require(bandSeed.add_gm_instrument(40,17,35,87)&&bandSeed.add_gm_instrument(73,997,96,101),"Band name fixture includes PChannels above16");
    auto bandRoot=Chunk::parse(bandSeed.save_bytes());bandRoot.children.push_back(info);bandRoot.children.push_back(unknown);
    const auto bandBefore=bandRoot.encode();BandDocument namedBand;namedBand.load(bandBefore);
    require(namedBand.name()==L"Original"&&!namedBand.dirty(),"Read Band native name without changing checkpoint");
    require(namedBand.set_name(L"検証 Band"),"Edit Unicode Band name");
    auto bandExpected=bandRoot;bandExpected.find("LIST","UNFO")->find("UNAM")->data=utf16(L"検証 Band");const auto bandAfter=bandExpected.encode();
    require(namedBand.save_bytes()==bandAfter&&namedBand.dirty(),"Band name changes only UNAM; GUID, instrument DWORDs, author and opaque padding exact");
    require(namedBand.instruments()[0].pchannel==17&&namedBand.instruments()[1].pchannel==997&&namedBand.instruments()[0].patch==40,"Band name leaves high PChannel assignments unchanged");
    require(namedBand.undo()&&namedBand.save_bytes()==bandBefore&&!namedBand.dirty()&&namedBand.can_redo(),"Band name Undo restores clean checkpoint and Redo");
    for(const auto& invalid:std::vector<std::wstring>{L"",std::wstring(256,L'x'),std::wstring(L"a\0b",3)}){
        require(!namedBand.set_name(invalid)&&namedBand.save_bytes()==bandBefore&&!namedBand.dirty()&&namedBand.can_redo(),"Invalid Band name preserves bytes, dirty state and Redo");
    }
    require(!namedBand.set_name(L"Original")&&namedBand.can_redo()&&namedBand.redo()&&namedBand.save_bytes()==bandAfter,"No-op Band name preserves redo transaction");
    namedBand.save((owned/L"NamedBand.bnp").wstring());BandDocument reloadedName;reloadedName.load(read_file((owned/L"NamedBand.bnp").wstring()));
    require(reloadedName.name()==L"検証 Band"&&reloadedName.save_bytes()==bandAfter&&!reloadedName.dirty()&&!reloadedName.can_undo(),"Named Band native reload exact with fresh history");
    require(namedBand.undo()&&namedBand.dirty()&&namedBand.redo()&&!namedBand.dirty(),"Saved Band name checkpoint tracks Undo/Redo dirty state");
    require(namedBand.set_name(std::wstring(255,L'n'))&&namedBand.name().size()==255&&!namedBand.set_name(std::wstring(256,L'n')),"Band uses existing name boundary255");
    BandDocument noBandName;const auto noBandNameBefore=noBandName.save_bytes();
    require(noBandName.name().empty()&&noBandName.set_name(L"Added Band")&&noBandName.undo()&&noBandName.save_bytes()==noBandNameBefore&&noBandName.redo(),"Absent Band name container added as one complete history transaction");
    for(unsigned malformed=0;malformed<4;++malformed){
        auto bad=bandRoot;
        if(malformed==0)bad.children.push_back(info);
        else if(malformed==1)bad.find("LIST","UNFO")->children.push_back(name);
        else if(malformed==2)bad.find("LIST","UNFO")->find("UNAM")->data={1};
        else bad.find("LIST","UNFO")->find("UNAM")->data=utf16(std::wstring(L"a\0b",3));
        BandDocument invalid;invalid.load(bad.encode());const auto bytes=invalid.save_bytes();
        rejected([&]{invalid.set_name(L"Wrong");},"Ambiguous or malformed Band optional name rejects");
        require(invalid.save_bytes()==bytes&&!invalid.dirty()&&!invalid.can_undo()&&!invalid.can_redo(),"Rejected Band name leaves all bytes and histories unchanged");
    }
    const auto namedIndex=host.open_band((owned/L"NamedBand.bnp").wstring());
    require(host.set_band_name(namedIndex,L"Project Band"),"Shared Band property edits owned Framework document");
    host.save_band(namedIndex,(owned/L"NamedBand.bnp").wstring());host.save_project((owned/L"Names.pro").wstring());
    require(host.set_band_name(namedIndex,L"Project Band 新名")&&host.undo_band(namedIndex)&&host.band_document(namedIndex).name()==L"Project Band"&&host.redo_band(namedIndex),"Framework Band name history remains independent");
    host.save_band(namedIndex,(owned/L"NamedBand.bnp").wstring());host.save_project((owned/L"Names.pro").wstring());
    const auto nativeProject=Chunk::parse(read_file((owned/L"Names.pro").wstring()));size_t updatedNames=0;
    std::function<void(const Chunk&)> inspectName=[&](const Chunk& c){if(c.id=="nnam"&&decode_utf16(c.data)==L"Project Band 新名")++updatedNames;for(const auto& child:c.children)inspectName(child);};inspectName(nativeProject);
    require(updatedNames==1,"Saving existing native Project refreshes exactly the named Band entry");
    Framework namedReload;namedReload.open_project((owned/L"Names.pro").wstring());
    const auto found=std::find_if(namedReload.band_documents().begin(),namedReload.band_documents().end(),[](const auto& d){return d.document->name()==L"Project Band 新名";});
    require(found!=namedReload.band_documents().end()&&found->document->save_bytes()==host.band_document(namedIndex).save_bytes()&&!found->document->dirty(),"Separate Framework restores native Project Band name and complete instrument payload");
}
